// Builds the plugin's generated files:
//   ../client.js            browser client, bundled from ../src/ (module-loader format)
//   ../lib/standalone.js    standalone browser client, including production React
//   ../client.export-html.js  lazy data chunk with the standalone + engine sources
//   ../lib/likec4.mjs       engine (entry.mjs) as an ES module, for the Host
//   ../client.likec4.js     engine as a module-loader chunk, loaded on demand by the client
//   ../client.icons-XX.js   icon pack shards (icons.mjs), loaded on demand for the icons shown
//   generated/icon-index.json  product name → icon id, bundled into the engine
// `node build.mjs client` rebuilds both clients (fast; refresh or render a new HTML).
// The icon pack is regenerated only when its inputs change (sets, rules, generator).
import { build } from 'esbuild'
import { writeFile, readFile, mkdir, readdir, unlink } from 'node:fs/promises'
import { createHash } from 'node:crypto'
import path from 'node:path'
import { generateIcons } from './icons.mjs'
import { shardFile } from '../src/iconrules.js'

const ID = 'dsh-diagram'
const CHUNK = 'client.likec4.js'
const only = process.argv[2]

/** Wraps a CommonJS bundle body into a module-loader definition. */
const loaderModule = (body, chunk, header = '') => `${header}window.__ModuleLoader__.load({\n\tid: ${JSON.stringify(ID)},\n${chunk ? `\tchunk: ${JSON.stringify(chunk)},\n` : ''}\tfactory: (require) => {\n\t\tvar module = { exports: {} };\n\t\tvar exports = module.exports;\n${body}\n\t\treturn module.exports;\n\t}\n});\n`

const client = await build({
  entryPoints: ['../src/main.js'], bundle: true, minify: false, platform: 'browser', target: 'es2022',
  format: 'cjs', external: ['react'], write: false, logLevel: 'warning', legalComments: 'none', charset: 'utf8',
})
await writeFile('../client.js', loaderModule(client.outputFiles[0].text, null, '// Generated by build/build.mjs from src/ — do not edit.\n'))
console.log('built ../client.js')

// Pin both packages to the same build-time installation: src/ lives outside build/,
// and a workspace may also have its own React. The DSH bundle stays external above.
await mkdir('../lib', { recursive: true })
const standalone = await build({
  entryPoints: ['../src/standalone.js'], bundle: true, minify: true, platform: 'browser', target: 'es2022',
  format: 'iife', outfile: '../lib/standalone.js', logLevel: 'warning', legalComments: 'none', charset: 'utf8',
  define: { 'process.env.NODE_ENV': '"production"' },
  // Keep the React license in HTML files too, which can be shared on their own.
  banner: { js: '/* React, React DOM and Scheduler\n' + await readFile('node_modules/react/LICENSE', 'utf8') + '\n*/' },
  alias: { react: path.resolve('node_modules/react'), 'react-dom': path.resolve('node_modules/react-dom') },
  metafile: true,
})
const standaloneBytes = Object.values(standalone.metafile.outputs).reduce((sum, output) => sum + output.bytes, 0)
console.log(`built ../lib/standalone.js (${Math.round(standaloneBytes / 1024)} KB)`)
// A data-only module, not another executing viewer. Keep it out of client.js
// and of the standalone bundle (which must never embed itself recursively).
async function exportAssets() {
  const bundle = await readFile('../lib/standalone.js', 'utf8')
  const engine = await readFile('../client.likec4.js', 'utf8')
  await writeFile('../client.export-html.js', loaderModule(`module.exports = ${JSON.stringify({ bundle, engine })};`, 'client.export-html.js'))
  console.log('built ../client.export-html.js (lazy HTML export assets)')
}
if (only === 'client') {
  await exportAssets()
  process.exit(0)
}

// ── icon pack ──────────────────────────────────────────────────────────────
async function iconStamp() {
  const h = createHash('sha256')
  for (const f of ['package-lock.json', 'icons.mjs', '../src/iconrules.js']) h.update(await readFile(f))
  return h.digest('hex')
}
await mkdir('generated', { recursive: true })
const stamp = await iconStamp()
let fresh = false
try {
  fresh = (await readFile('generated/icon-stamp', 'utf8')) === stamp && (await readdir('..')).includes(shardFile(0))
  if (fresh) await readFile('generated/icon-index.json')
} catch {
  fresh = false
}
if (fresh) console.log('icon pack up to date')
else {
  const { index, shards } = await generateIcons({ log: (m) => console.log(m) })
  for (const f of (await readdir('..')).filter((f) => /^client\.icons-\d+\.js$/.test(f))) await unlink('../' + f)
  for (let i = 0; i < shards.length; i++) {
    const chunk = shardFile(i)
    await writeFile('../' + chunk, loaderModule(`module.exports = ${JSON.stringify(shards[i])};`, chunk))
  }
  await writeFile('generated/icon-index.json', JSON.stringify(index))
  await writeFile('generated/icon-stamp', stamp)
  console.log(`built ../client.icons-*.js (${shards.length}) and generated/icon-index.json`)
}

// ── engine ─────────────────────────────────────────────────────────────────
await mkdir('../lib', { recursive: true })
await build({
  entryPoints: ['entry.mjs'], bundle: true, minify: true, platform: 'browser',
  format: 'esm', outfile: '../lib/likec4.mjs', logLevel: 'warning', legalComments: 'none',
})
const cjs = await build({
  entryPoints: ['entry.mjs'], bundle: true, minify: true, platform: 'browser',
  format: 'cjs', write: false, logLevel: 'warning', legalComments: 'none',
})
await writeFile(`../${CHUNK}`, loaderModule(cjs.outputFiles[0].text, CHUNK))
console.log('built ../lib/likec4.mjs and ../' + CHUNK)
await exportAssets()
